return {["fb221_01"]={["down"]=[[fb221_03]],["dsc"]=[[奇险天都著，遥观亦有缘；大雄无与并，苍浑莫之先。站在此处，登高而望远。悬崖绝壁不显于色，天都群景一览无余。地虽险，但景更绝。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_01]],["item1"]=[[fbwp04]],["name"]=[[天都绝壁]],["permission"]=2,["role1"]=[[fbnpc29]],["role2"]=[[fbnpc29b]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_02"]={["dsc"]=[[文无第一，武无第二，习武之人谁不不想做那个独步武林，唯求一败的天下第一，此楼便由此得名。楼依山而建，凌霄绝顶，立于此地可见天地苍茫，可览众山势小，猛勇之气陡然而增。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_02]],["item1"]=[[25tzbosscf03]],["item2"]=[[25tzbosscf04]],["item3"]=[[25tzbosscf05]],["item4"]=[[25tzbosscf06]],["name"]=[[独求一败楼]],["permission"]=2,["right"]=[[fb221_03]],["role1"]=[[22lunjiandoor]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_03"]={["down"]=[[fb221_05]],["dsc"]=[[天都峰上一块宽阔的平台，被设立为武林盟内唯一广场，用于武林盟弟子试剑比武。上通绝壁，下通顶峰，左右两旁竟是高楼庙宇万丈起。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb221_03]],["left"]=[[fb221_02]],["name"]=[[试剑广场]],["permission"]=2,["right"]=[[fb221_04]],["role1"]=[[fbnpc26]],["role2"]=[[fbnpc27]],["role3"]=[[fbnpc28]],["role4"]=[[fbnpc28d]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_01]],["visible"]=1},["fb221_04"]={["dsc"]=[[都说文无第一，武无第二，文笔再好的人也不敢自夸天下第一，而武艺高强之人却往往自称天下无敌，故此庙正因此而得名。庙堂占地不广，纸窗木扉，青砖白瓦。站在这天都峰面对着这样一座庙宇，望之心生谦逊，观之心如止水。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_04]],["left"]=[[fb221_03]],["name"]=[[文无第一庙]],["permission"]=2,["role1"]=[[fbnpc48a]],["role2"]=[[fbnpc48b]],["role3"]=[[fbnpc48c]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_05"]={["down"]=[[fb221_16]],["dsc"]=[[这是一座石洞，洞口有一巧石，似醉仙斜卧。相传这是王母发现蟠桃被盗后，特派仙人在此把守，因此人称“仙人把洞门”。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb221_05]],["item1"]=[[fbtrigger02]],["name"]=[[仙人把洞门]],["permission"]=1,["right"]=[[fb221_06]],["role1"]=[[fbnpc20]],["role2"]=[[fbnpc21]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_03]],["visible"]=1},["fb221_06"]={["dsc"]=[[石室开阔，可容百人，其中石笋目不暇接，形态各异，错落有致，也为一奇观。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_06]],["left"]=[[fb221_05]],["name"]=[[天都石室]],["permission"]=1,["right"]=[[fb221_07]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_07"]={["dsc"]=[[天都石室中的一座石穴，幽暗森冷，让人不禁背脊发寒。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_07]],["left"]=[[fb221_06]],["name"]=[[反思洞]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_08"]={["down"]=[[fb221_14]],["dsc"]=[[这里就是三姑洞，山道自洞中穿过。相传曾有三位仙姑采药救生灵，三位仙姑就居住于这洞中，故称为“三姑洞”。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_08]],["name"]=[[三姑洞]],["permission"]=2,["role1"]=[[24jhwxupnpc01]],["role2"]=[[24jhwxupnpc02]],["role3"]=[[24jhwxupnpc03]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_09"]={["down"]=[[fb221_15]],["dsc"]=[[这里就是佛光台，山台并未有出奇之处，但眼前云雾灵动，你不禁驻足观望。随着云雾飘动，云海愈深，忽有佛光显现，衬得这奇峰更奇，怪石愈怪，此情此景如梦似幻。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_09]],["name"]=[[佛光台]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_10"]={["down"]=[[fb221_17]],["dsc"]=[[下了鲫鱼背，过了仙桃洞，回首而望便见洞顶有三块圆石相垒，状似一盘蟠桃，石缝中生出苍松，恰似桃柄桃叶。待斜阳夕照，石尖微现红光，犹如熟透的蟠桃。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_10]],["item1"]=[[newdrwp01a]],["name"]=[[仙桃石]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_11"]={["down"]=[[fb221_18]],["dsc"]=[[这是一块巨石，横架于两山之间，是为一座天然石桥。石桥形似彩虹飞跨，云雾翻滚桥下，登上此桥有如登临仙境，故名“天桥”。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_11]],["name"]=[[天桥]],["permission"]=2,["role1"]=[[fbnpc37]],["role2"]=[[wanjiaNPC]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_12"]={["dsc"]=[[这是一间依山而筑的小寺，背依嵯峨山峰，前临千仞绝壁，周围万木葱茏，碧云堆翠。廊下有游人留记来到半山坐一坐，再走五里天上天。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_12]],["name"]=[[半山寺]],["permission"]=2,["right"]=[[fb221_13]],["role1"]=[[fbnpc33]],["role2"]=[[fbnpc34]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_13"]={["dsc"]=[[蜿蜒小路旁有一块巨石横空而出，孤悬于崖外。石面狭窄，仅容一人，下方则是万丈深渊，立于其上需要莫大的勇气，故称为试胆石。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_13]],["left"]=[[fb221_12]],["name"]=[[试胆石]],["permission"]=2,["right"]=[[fb221_14]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_14"]={["dsc"]=[[这是半山寺通往【天都绝顶】的必经路，陡峭的山道三曲回折，身旁便是悬崖绝壁，崖边仅围有一根铁索。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_14]],["item1"]=[[22qjqzcf04]],["left"]=[[fb221_13]],["name"]=[[三道弯]],["permission"]=2,["right"]=[[fb221_15]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_08]],["visible"]=1},["fb221_15"]={["down"]=[[fb221_24]],["dsc"]=[[山道蜿蜒向上，在东侧的石崖壁上凌空长出了一截薄薄的石板，宛如是助仙人上下天庭的跳板，故称为跳板石。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_15]],["left"]=[[fb221_14]],["name"]=[[跳板石]],["permission"]=2,["right"]=[[fb221_16]],["role1"]=[[fbnpc30]],["role2"]=[[qixinpc2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_09]],["visible"]=1},["fb221_16"]={["down"]=[[fb221_30]],["dsc"]=[[这里就是天都绝顶，险峭雄奇，气势博大，四周云海环绕，身处其中，爽心豁目。立于峰头，极目远眺，云山相接，俯瞰群山，千峰竞秀，美不胜收。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_16]],["item1"]=[[fbwp01a]],["item2"]=[[fbwp03]],["left"]=[[fb221_15]],["name"]=[[天都绝顶]],["permission"]=1,["right"]=[[fb221_17]],["role1"]=[[fbnpc24b]],["role2"]=[[25huiyuecyshop]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_05]],["visible"]=1},["fb221_17"]={["down"]=[[fb221_25]],["dsc"]=[[这里便是鲫鱼背，乃天都峰上最为奇险之地，因颇似波涛之中的鲫鱼之背而得名。山坡陡峭，小道仅容一人而过，行至坡顶，两侧皆是万丈深渊，风吹云涌之时，仿佛山摇石动，甚为惊险。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_17]],["left"]=[[fb221_16]],["name"]=[[鲫鱼背]],["permission"]=2,["right"]=[[fb221_18]],["role1"]=[[fbnpc35]],["role2"]=[[fbnpc36]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_10]],["visible"]=1},["fb221_18"]={["dsc"]=[[这有一小块山台供游人小憩，旁有屏石，上刻“天山玉屏”。于山台前眺，便见玉屏峰，峰壁如玉雕屏障，峰前有苍松掩映的文殊台，景色奇绝，宛如置于画中。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_18]],["left"]=[[fb221_17]],["name"]=[[天上玉屏]],["permission"]=2,["right"]=[[fb221_19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_11]],["visible"]=1},["fb221_19"]={["dsc"]=[[行至耕云峰，又见一巧石。神似观音亭亭玉立于云海间，头戴风帽，衣巾飘曳，令人不禁心生敬畏。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_19]],["left"]=[[fb221_18]],["name"]=[[观音石]],["permission"]=2,["right"]=[[fb221_20]],["role1"]=[[fbnpc39]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_20"]={["dsc"]=[[这块巧石似童子，跪于观音石前，像是在虔诚朝拜。两块巧石以天地为纸，画出一幅“童子拜观音”。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_20]],["left"]=[[fb221_19]],["name"]=[[童子石]],["permission"]=2,["right"]=[[fb221_21]],["role1"]=[[fbnpc38]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_21"]={["dsc"]=[[这里就是老道口，先人凿石为阶，攀草牵棘而上，开出一条山道。自峰下仰望，这山道犹如天边悬梯，垂贴于石壁，人行其上，如壁虎攀墙，稍有不慎便会失足滑落，无物可挡。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_21]],["left"]=[[fb221_20]],["name"]=[[老道口]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_22"]={["down"]=[[fb221_28]],["dsc"]=[[中华阁的厢房。虽是平平无奇的砖瓦房，但无论是布局还是装点，都让人莫名觉得惬意。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_22]],["item1"]=[[xianxianshuanadd]],["item2"]=[[newdrwp02a]],["name"]=[[厢房]],["permission"]=2,["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_23"]={["down"]=[[fb221_29]],["dsc"]=[[这里是中华阁的二楼，是一间静僻典雅的房间。房间内木桌竹椅一应俱全，窗外便是山间美景，处高而望远。时不时更有凉风袭来，舒适且安心。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_23]],["item1"]=[[sanrenmindskillnpc2]],["name"]=[[二楼]],["permission"]=2,["role1"]=[[qixinpc3]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_24"]={["dsc"]=[[此处山台石质特殊，每逢朝升夕落时，这山台便会发出莹莹光辉，自远处观看，就如水晶打造一般，令人称奇。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_24]],["name"]=[[水晶台]],["permission"]=2,["role1"]=[[fbnpc31]],["role2"]=[[fbnpc32]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_15]],["visible"]=1},["fb221_25"]={["dsc"]=[[天都风景卓绝，多怪石奇松，此时眼前便有一棵奇松，名唤探海松。此松根扎悬崖，立于山峰陡腰，枝繁叶茂，侧枝倾伸，犹如苍龙探海，戏搅浮云。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_25]],["name"]=[[探海松]],["permission"]=2,["role1"]=[[25cyshopjianghuqg]],["role2"]=[[25cyshopjianghubq]],["role3"]=[[25cyshopjianghuqj]],["role4"]=[[25cyshopjianghung]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_17]],["visible"]=1},["fb221_26"]={["down"]=[[fb221_31]],["dsc"]=[[由江湖第一号情报商人百晓生所设，建设在天都峰上武林盟旁。堂内飘着似有若无的檀香，内外堂被门帘和栏杆所分隔开来。成千上万的书卷在后面堆积成山。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_26]],["name"]=[[百晓堂]],["permission"]=2,["role1"]=[[fbnpc43a]],["role2"]=[[fbnpc43b]],["role3"]=[[fbnpc43c]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_27"]={["dsc"]=[[新造不久的马厩，棚内放着干净的水槽和干草。左右两侧的墙壁上，一侧挂着各式的马鞍，一侧挂着材质不同的马鞭。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_27]],["name"]=[[马厩]],["permission"]=2,["right"]=[[fb221_28]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_28"]={["down"]=[[fb221_33]],["dsc"]=[[这里是中华阁的后院。依山而建，旁边是马厩和两间厢房。鸡犬在院子里四处嬉戏觅食，一袋袋粮油米面整齐地堆放在小车上，一串串辣椒挂在墙边，为这高峻的山峰平添几分热闹的气息。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_28]],["item1"]=[[xianxianaddnpc1]],["left"]=[[fb221_27]],["name"]=[[后院]],["permission"]=2,["right"]=[[fb221_29]],["role1"]=[[fbnpc41]],["stepMusic"]=[[mudiban]],["up"]=[[fb221_22]],["visible"]=1},["fb221_29"]={["dsc"]=[[一间设立在山间的竹舍，一个精致的雅阁。雅阁上挂着“中华阁”三个字的匾额，门边贴着门联，上联卧听风来晚。下联坐看云起时。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_29]],["item1"]=[[wxtpjq_05]],["left"]=[[fb221_28]],["name"]=[[中华阁]],["permission"]=2,["right"]=[[fb221_30]],["role1"]=[[fbnpc40]],["role2"]=[[fbnpc40a]],["role3"]=[[25bmartialnpc]],["stepMusic"]=[[mudiban]],["up"]=[[fb221_23]],["visible"]=1},["fb221_30"]={["down"]=[[fb221_34]],["dsc"]=[[一路行来，山隘险阻，山路崎岖，再过此路后即可登顶天都峰，真可谓是苦尽甘来。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_30]],["item1"]=[[25tzbosscf02]],["left"]=[[fb221_29]],["name"]=[[巅峰之路]],["permission"]=1,["right"]=[[fb221_31]],["role1"]=[[fbnpc17]],["role2"]=[[fbnpc18]],["role3"]=[[fbnpc19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_16]],["visible"]=1},["fb221_31"]={["down"]=[[fb221_35]],["dsc"]=[[天都峰上建造的一处宽阔院落。据说是由某一届的“江湖三友”百晓生、千机老人、万贯婆婆共同出资建造，专为中原武林盟提供物资和各种需求。院落四通八达，可通往百晓堂、千机阁、万贯钱庄三个地方。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb221_31]],["item1"]=[[21masktrigger01]],["left"]=[[fb221_30]],["name"]=[[武林商盟]],["permission"]=2,["right"]=[[fb221_32]],["role1"]=[[fbnpc42]],["role2"]=[[25wshtamartial]],["role3"]=[[25wshtbmartial]],["role4"]=[[25wshtdmartial]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_26]],["visible"]=1},["fb221_32"]={["dsc"]=[[由江湖第一号回收商人万贯婆婆所设，建设在天都峰上武林盟旁。虽是钱庄，但里面除了些许储物柜外，家具设施尽显寒酸，老板可谓是抠门到了极点。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_32]],["left"]=[[fb221_31]],["name"]=[[万贯钱庄]],["permission"]=2,["role1"]=[[fbnpc45]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_33"]={["dsc"]=[[中华阁的厢房。虽是平平无奇的砖瓦房，但无论是布局还是装点，都让人莫名觉得惬意。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_33]],["name"]=[[厢房]],["permission"]=2,["stepMusic"]=[[mudiban]],["up"]=[[fb221_28]],["visible"]=1},["fb221_34"]={["down"]=[[fb221_37]],["dsc"]=[[迢迢山径峻，万仞险隘危。从此处起山路更加险峻，蜿蜒深入云海间，细看只觉胆寒。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_34]],["name"]=[[险阻山隘]],["permission"]=1,["role1"]=[[fbnpc14a]],["role2"]=[[fbnpc15a]],["role3"]=[[fbnpc16a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_30]],["visible"]=1},["fb221_35"]={["dsc"]=[[由江湖第一号武学商人千机老人所设，建设在天都峰上武林盟旁。外堂灯火通明，内堂却漆黑一片，什么也看不见。似乎有些人影藏于黑暗中，观察着每一位有奇怪举动的访客，整个阁中，不像看上去这样只有那么些人。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_35]],["name"]=[[千机阁]],["permission"]=2,["role1"]=[[fbnpc44]],["stepMusic"]=[[mudiban]],["up"]=[[fb221_31]],["visible"]=1},["fb221_36"]={["dsc"]=[[眼前便是有名的奇石“五老上天都”，五石宛如五位老翁，栩栩如生，其中一石作前导状，亦称“老人峰”。五石各具形态，唯有老人峰最具无畏之意，愈看愈觉生动无比。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_36]],["name"]=[[老人峰]],["permission"]=2,["right"]=[[fb221_37]],["role1"]=[[fbnpc12]],["role2"]=[[fbnpc13]],["role3"]=[[syduihuannpc]],["role4"]=[[sybulingnpc01]],["role5"]=[[22sanrencynpc]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_37"]={["down"]=[[fb221_38]],["dsc"]=[[山路蜿蜒，越发的艰险。步移景换，“金鸡”已不见，却见五石宛如五位老翁，携手持杖，向着天都峰顶去，这便是有名的奇石“五老上天都”。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_37]],["left"]=[[fb221_36]],["name"]=[[五老上天都]],["permission"]=1,["role1"]=[[fbnpc08]],["role2"]=[[fbnpc09]],["role3"]=[[fbnpc10]],["role4"]=[[fbnpc11]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_34]],["visible"]=1},["fb221_38"]={["dsc"]=[[山路蜿蜒，越发的艰险。仰观山峰，山腰处上有一巨石，状似雄鸡，面朝天门坎，振翅欲啼。正值朝升之时，雄鸡仿佛渡上了一层金光，令人称奇。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_38]],["item1"]=[[sanrenmindskillnpc1]],["leftDown"]=[[fb221_39]],["name"]=[[金鸡叫天门]],["permission"]=1,["role1"]=[[fbnpc07]],["role2"]=[[22thepastShop]],["stepMusic"]=[[jiaobu]],["up"]=[[fb221_37]],["visible"]=1},["fb221_39"]={["dsc"]=[[这就是晋升石阶，依山而建，随着山势曲折而上，一步一阶梯，终会登顶览群峰。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_39]],["leftDown"]=[[fb221_40]],["name"]=[[晋升石阶]],["permission"]=1,["rightUp"]=[[fb221_38]],["role1"]=[[fbnpc05]],["role2"]=[[fbnpc06]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_40"]={["dsc"]=[[过了天门坎，便豁然开朗，好似入了天界中，远处是巍峨山峰，有长松落落，眼前小道蜿蜒，有卉木蒙蒙。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_40]],["item1"]=[[25tzbosscf01]],["name"]=[[入门小道]],["permission"]=1,["rightDown"]=[[fb221_41]],["rightUp"]=[[fb221_39]],["role1"]=[[fbnpc03]],["role2"]=[[fbnpc04]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_41"]={["dsc"]=[[“过此成仙侣，归来无俗客”，这里便是天门坎。两面奇峰直入云霄，一条小道从中间穿过，走过其中宛如跨过“天门”，故称为“天门坎”。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_41]],["item1"]=[[fbtrigger03]],["leftUp"]=[[fb221_40]],["name"]=[[天门坎]],["permission"]=1,["rightDown"]=[[fb221_42]],["role1"]=[[fbnpc01a]],["role2"]=[[fbnpc02a]],["role3"]=[[breaksr]],["role4"]=[[22breakyichusrnpc]],["role5"]=[[22breakyichusrnpc02]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_42"]={["dsc"]=[[这里就是龙蟠坡，陡峭石阶路像是弯曲的巨龙蟠卧，抬眼可见天都峰卓立地表，健骨辣桀，壮丽非凡。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb221_42]],["item1"]=[[wxtpjq_18]],["item2"]=[[wxtpjq_19]],["item3"]=[[wxtpjq_20]],["item4"]=[[wxtpjq_01]],["item5"]=[[wxtpjq_08]],["item6"]=[[wxtpjq_11]],["item7"]=[[wxtpjq_15]],["left"]=[[fb221_51]],["leftUp"]=[[fb221_41]],["name"]=[[龙蟠坡]],["permission"]=1,["rightUp"]=[[fb221_46]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_43"]={["dsc"]=[[这是一座富丽堂皇的府邸，大门门楣上挂着一道牌匾，上面用金漆写着两个大字——“金府”。从大门进入府中，先过垂花门，再穿游廊，才见内院。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_43]],["leftDown"]=[[fb221_44]],["name"]=[[金府]],["permission"]=1,["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_44"]={["dsc"]=[[这是天都峰山脚下的一处集市，南来北往的行商走卒、江湖中人往往都会在此处歇脚。杂乱的人群中传出各种吆喝、叫卖的声音，显得很是热闹。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb221_44]],["leftDown"]=[[fb221_46]],["name"]=[[集市]],["permission"]=1,["right"]=[[fb221_45]],["rightUp"]=[[fb221_43]],["role1"]=[[23srxinfaupnpc]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_45"]={["dsc"]=[[这是天都峰山脚下的一处集市，南来北往的行商走卒、江湖中人往往都会在此处歇脚。杂乱的人群中传出各种吆喝、叫卖的声音，显得很是热闹。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb221_45]],["left"]=[[fb221_44]],["leftDown"]=[[fb221_47]],["name"]=[[集市]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_46"]={["dsc"]=[[这是天都峰山脚下的一处集市，南来北往的行商走卒、江湖中人往往都会在此处歇脚。杂乱的人群中传出各种吆喝、叫卖的声音，显得很是热闹。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb221_46]],["item1"]=[[wxtpjq_07]],["item2"]=[[wxtpjq_12]],["leftDown"]=[[fb221_42]],["name"]=[[集市]],["permission"]=1,["right"]=[[fb221_47]],["rightUp"]=[[fb221_44]],["role1"]=[[sy2npc_03]],["role2"]=[[sy4npc_05]],["role3"]=[[sy6npc_09]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_47"]={["dsc"]=[[这是天都峰山脚下的一处集市，南来北往的行商走卒、江湖中人往往都会在此处歇脚。杂乱的人群中传出各种吆喝、叫卖的声音，显得很是热闹。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb221_47]],["item1"]=[[sy1chufa]],["item2"]=[[sy2chufa]],["item3"]=[[sy3chufa01]],["item4"]=[[sy10chufa01]],["item5"]=[[sy11chufa02]],["item6"]=[[sy10chufa01]],["item7"]=[[sy12chufa01]],["item8"]=[[sy13chufa02]],["left"]=[[fb221_46]],["name"]=[[集市]],["permission"]=1,["right"]=[[fb221_48]],["rightUp"]=[[fb221_45]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb221_48"]={["dsc"]=[[这是一处距离天都峰集市不远的院落。小院三面被竹林围绕，通人的一面用篱笆简单围成门扉和外墙。从篱笆们进入院内，可见一个三丈见方的屋子。屋子紧贴着西侧竹林，屋内除了一张草席之外，摆满了各类制作脸谱的工具及材料。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_48]],["item1"]=[[sy3chufa02]],["item10"]=[[sy11chufa01]],["item11"]=[[sy13chufa01]],["item2"]=[[sy4chufa01]],["item3"]=[[sy4chufa02]],["item4"]=[[sy5chufa]],["item5"]=[[sy6chufa]],["item6"]=[[sy7chufa]],["item7"]=[[sy8chufa]],["item8"]=[[sy9chufa]],["item9"]=[[sy10chufa02]],["left"]=[[fb221_47]],["name"]=[[小院]],["permission"]=1,["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_49"]={["dsc"]=[[天下客栈内北侧房间，房内设有楼梯通向高层，此为天下客栈招待达官显贵之所。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_49]],["item1"]=[[wxtpjq_03]],["item2"]=[[wxtpjq_09]],["item3"]=[[wxtpjq_14]],["item4"]=[[wxtpjq_17]],["leftDown"]=[[fb221_50]],["name"]=[[天馆]],["permission"]=1,["rightDown"]=[[fb221_51]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_50"]={["dsc"]=[[天下客栈后院，通常不会让外人进入。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_50]],["item1"]=[[wxtpjq_04]],["name"]=[[后院]],["permission"]=1,["right"]=[[fb221_51]],["rightDown"]=[[fb221_52]],["rightUp"]=[[fb221_49]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_51"]={["dsc"]=[[天下客栈主楼，远观气势辉宏，正门上一块硕大的牌匾“天下客栈”四个金色大字历历在目格外气派。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_51]],["item1"]=[[wxtpjq_02]],["item2"]=[[wxtpjq_06]],["item3"]=[[wxtpjq_10]],["item4"]=[[wxtpjq_16]],["left"]=[[fb221_50]],["leftDown"]=[[fb221_52]],["leftUp"]=[[fb221_49]],["name"]=[[天下客栈]],["permission"]=1,["right"]=[[fb221_42]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb221_52"]={["dsc"]=[[天下客栈内南侧房间，房内设有楼梯通向高层，此为天下客栈招待江湖人士之所。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb221_52]],["item1"]=[[wxtpjq_13]],["leftUp"]=[[fb221_50]],["name"]=[[地舍]],["permission"]=1,["rightUp"]=[[fb221_51]],["stepMusic"]=[[mudiban]],["visible"]=1}}0